(function() { 
// 定义7种颜色对应的类名
  const colorClasses = [
    'agent-logo-yellow',
    'agent-logo-blue',
    'agent-logo-green',
    'agent-logo-pink',
    'agent-logo-purple',
    'agent-logo-red',
    'agent-logo-green2'
  ];
  // 生成0-7的随机数
  const randomIndex = Math.floor(Math.random() * 7);
  // 动态返回对应类名的div
  return `<div class="${colorClasses[randomIndex]}"></div>`;
})()

